mapper.select:
SELECT s.studentid, s.studentno, s.studentname, s.sex, s.phone, s.email, s.address,
       s.classid, s.majorid, s.createtime, s.avatar, c.classname, m.majorname
FROM student s
LEFT JOIN classinfo c ON s.classid = c.classid
LEFT JOIN major m ON s.majorid = m.majorid


        AND (s.studentno LIKE CONCAT('%', #{keyword}, '%') OR s.studentname LIKE CONCAT('%', #{keyword}, '%'))


        AND s.classid = #{classid}


        AND s.majorid = #{majorid}


ORDER BY s.studentid
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM student s


        AND (s.studentno LIKE CONCAT('%', #{keyword}, '%') OR s.studentname LIKE CONCAT('%', #{keyword}, '%'))


        AND s.classid = #{classid}


        AND s.majorid = #{majorid}

SELECT studentid, studentno, studentname, password, sex, phone, email, address, classid, majorid, createtime, avatar
FROM student
WHERE studentno = #{studentno}

mapper.update:
UPDATE student
SET studentno = #{studentno}, studentname = #{studentname}, password = #{password}, sex = #{sex},
    phone = #{phone}, email = #{email}, address = #{address}, classid = #{classid}, majorid = #{majorid}, avatar = #{avatar}
WHERE studentid = #{studentid}
